export function VendorServicesMarquee({ vendor }: { vendor: VendorKey }) {
  const data = VENDOR_CATALOG[vendor] || VENDOR_CATALOG.aws;
  // Duplicate for seamless infinite loop
  const marqueeItems = [...data.services, ...data.services];

  return (
    <section id="services-worked-on" className="w-full py-16 md:py-20 bg-black border-b border-zinc-900/60 relative overflow-hidden scroll-mt-24 select-none">
      {/* High performance CSS marquee animation */}
      <style>{`
        @keyframes vendor-marquee {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
        .vendor-marquee-track {
          display: flex;
          width: max-content;
          animation: vendor-marquee 32s linear infinite;
        }
        .vendor-marquee-container:hover .vendor-marquee-track {
          animation-play-state: paused;
        }
      `}</style>

      {/* Ambient background glow */}
      <div
        aria-hidden
        className="pointer-events-none absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[350px] rounded-full blur-[120px] opacity-20"
        style={{ background: "radial-gradient(circle, #E11D48 0%, rgba(225,29,72,0.3) 35%, transparent 70%)" }}
      />

      <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12 relative z-10">
        {/* Section Headings */}
        <div className="mb-10 text-center max-w-3xl mx-auto">
          <span className="text-sm sm:text-base font-bold tracking-[0.25em] uppercase text-rose-500 mb-3.5 block">
            {data.kicker}
          </span>
          <h2 className="text-2xl sm:text-3xl lg:text-4xl font-bold tracking-tight leading-tight text-white">
            {data.title} <span className="text-rose-500">{data.titleHighlight}</span>
          </h2>
        </div>
      </div>

      {/* Infinite Rolling Cards Marquee */}
      <div className="vendor-marquee-container w-full overflow-hidden relative py-2">
        {/* Left & Right Smooth Fade Overlays */}
        <div className="absolute left-0 top-0 bottom-0 w-16 sm:w-28 bg-gradient-to-r from-black via-black/80 to-transparent pointer-events-none z-20" />
        <div className="absolute right-0 top-0 bottom-0 w-16 sm:w-28 bg-gradient-to-l from-black via-black/80 to-transparent pointer-events-none z-20" />

        <div className="vendor-marquee-track gap-4 sm:gap-5 px-3">
          {marqueeItems.map((item, idx) => (
            <div
              key={`${item.name}-${idx}`}
              className="relative w-44 sm:w-52 h-36 sm:h-40 rounded-2xl border border-zinc-800/80 bg-zinc-950/70 p-4 sm:p-5 flex flex-col items-center justify-between text-center group cursor-pointer hover:border-rose-500/50 hover:bg-zinc-900/60 transition-all duration-300 hover:-translate-y-1 hover:shadow-[0_8px_24px_rgba(244,63,94,0.12)] shrink-0 select-none overflow-hidden"
            >
              {/* Subtle top category badge */}
              <span className="text-[10px] sm:text-[11px] font-mono uppercase tracking-wider text-zinc-500 group-hover:text-rose-400 transition-colors font-medium">
                {item.badge}
              </span>

              {/* Icon */}
              <div className="w-10 h-10 sm:w-12 sm:h-12 flex items-center justify-center my-1 group-hover:scale-110 transition-transform duration-300">
                <svg
                  viewBox={item.viewBox}
                  className="w-full h-full object-contain filter drop-shadow-sm"
                  dangerouslySetInnerHTML={{ __html: item.body }}
                />
              </div>

              {/* Service Name */}
              <h4 className="text-xs sm:text-sm font-semibold text-zinc-200 group-hover:text-white transition-colors line-clamp-2 leading-tight">
                {item.name}
              </h4>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
